import React, { useState } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';

const Header: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const { user, logout } = useAuth();
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);

  const handleLogout = () => {
    logout();
    navigate('/login');
    setIsDropdownOpen(false);
  };

  const isActive = (path: string) => location.pathname === path;

  const toggleDropdown = () => {
    setIsDropdownOpen(!isDropdownOpen);
  };

  const closeDropdown = () => {
    setIsDropdownOpen(false);
  };

  return (
    <header className="header">
      <div className="header-container">
        <Link to="/" className="header-logo">
          <span className="logo-text">Цензура ПД</span>
        </Link>
        
        <nav className="header-nav">
          <Link 
            to="/" 
            className={`nav-link ${isActive('/') ? 'active' : ''}`}
          >
            🏠 Главная
          </Link>
          
          {user ? (
            <>
              <Link 
                to="/redaction" 
                className={`nav-link ${isActive('/redaction') ? 'active' : ''}`}
              >
                🖼️ Редактор
              </Link>
              <Link 
                to="/status" 
                className={`nav-link ${isActive('/status') ? 'active' : ''}`}
              >
                📊 Статус
              </Link>
              
              <div 
                className="user-menu" 
                onMouseEnter={() => setIsDropdownOpen(true)}
                onMouseLeave={() => setIsDropdownOpen(false)}
              >
                <div 
                  className="user-badge"
                  onClick={toggleDropdown}
                  style={{ cursor: 'pointer' }}
                >
                  <span className="user-icon">
                    {user.is_admin ? '👑' : '👤'}
                  </span>
                  <span className="username">{user.username}</span>
                  {user.is_admin && (
                    <span className="admin-badge">Admin</span>
                  )}
                  <span className="dropdown-arrow">
                    {isDropdownOpen ? '▲' : '▼'}
                  </span>
                </div>
                
                {isDropdownOpen && (
                  <div className="dropdown-menu">
                    <div className="user-info">
                      <p><strong>Username:</strong> {user.username}</p>
                      {user.email && <p><strong>Email:</strong> {user.email}</p>}
                      {user.created_at && (
                        <p><strong>Joined:</strong> {new Date(user.created_at).toLocaleDateString('ru-RU')}</p>
                      )}
                      <div className="storage-info">
                        <p><strong>Storage:</strong> MinIO</p>
                        {user.minio_folder && <p><strong>Folder:</strong> {user.minio_folder}</p>}
                      </div>
                    </div>
                    <div className="dropdown-actions">
                      <button 
                        onClick={() => {
                          navigate('/profile');
                          closeDropdown();
                        }} 
                        className="dropdown-button"
                      >
                        Профиль
                      </button>
                      <button 
                        onClick={handleLogout} 
                        className="dropdown-button logout"
                      >
                        Выйти
                      </button>
                    </div>
                  </div>
                )}
              </div>
            </>
          ) : (
            <>
              <Link 
                to="/login" 
                className={`nav-link ${isActive('/login') ? 'active' : ''}`}
              >
                🔐 Войти
              </Link>
              <Link 
                to="/register" 
                className={`nav-link ${isActive('/register') ? 'active' : ''}`}
              >
                📝 Регистрация
              </Link>
            </>
          )}
          
          <Link 
            to="/about" 
            className={`nav-link ${isActive('/about') ? 'active' : ''}`}
          >
            ℹ️ О проекте
          </Link>
        </nav>
      </div>
    </header>
  );
};

export default Header;
